import fs from "node:fs";
import path from "node:path";

const root =
  process.cwd();

const packName =
  "Animated Effects UI Polish Pack 10";

const marker =
  "AE_UI_POLISH_PACK_10_START";

function fail(
  message,
) {
  console.error(
    "\nERROR:",
    message,
  );
  process.exit(
    1,
  );
}

if (
  !fs.existsSync(
    path.join(
      root,
      "pnpm-workspace.yaml",
    ),
  )
) {
  fail(
    "Uruchom z katalogu głównego aplikacja-turnieje-live.",
  );
}

const styleRelative =
  "artifacts/animated-effects/src/style.css";

const mainRelative =
  "artifacts/animated-effects/src/main.ts";

const characterRelative =
  "artifacts/animated-effects/src/pack09/customization.ts";

const uiRelative =
  "artifacts/animated-effects/src/pack09/uiPolish.ts";

for (
  const relative of [
    styleRelative,
    mainRelative,
    characterRelative,
  ]
) {
  if (
    !fs.existsSync(
      path.join(
        root,
        relative,
      ),
    )
  ) {
    fail(
      "Brak wymaganego pliku: " +
      relative +
      ". Pack 10 wymaga zainstalowanego Pack 09.",
    );
  }
}

const styleFile =
  path.join(
    root,
    styleRelative,
  );

if (
  fs.readFileSync(
    styleFile,
    "utf8",
  )
    .includes(
      marker,
    )
) {
  console.log(
    "Pack 10 UI jest już zainstalowany.",
  );
  process.exit(
    0,
  );
}

const stamp =
  new Date()
    .toISOString()
    .replace(
      /[:.]/g,
      "-",
    )
    .replace(
      "T",
      "_",
    )
    .replace(
      "Z",
      "",
    );

const backupRoot =
  path.join(
    root,
    ".ae-pack-backup",
    `pack-10-ui-polish-${stamp}`,
  );

const touched = [
  styleRelative,
  mainRelative,
  uiRelative,
];

const existed = [];

for (
  const relative of
    touched
) {
  const source =
    path.join(
      root,
      relative,
    );

  if (
    !fs.existsSync(
      source,
    )
  ) {
    continue;
  }

  existed.push(
    relative,
  );

  const backup =
    path.join(
      backupRoot,
      relative,
    );

  fs.mkdirSync(
    path.dirname(
      backup,
    ),
    {
      recursive:
        true,
    },
  );

  fs.copyFileSync(
    source,
    backup,
  );
}

fs.mkdirSync(
  backupRoot,
  {
    recursive:
      true,
  },
);

fs.writeFileSync(
  path.join(
    backupRoot,
    "backup-manifest.json",
  ),
  JSON.stringify(
    {
      pack:
        packName,
      touched,
      existed,
    },
    null,
    2,
  ) + "\n",
  "utf8",
);

const uiModule =
  Buffer.from(
    '',
    "hex",
  ).toString(
    "utf8",
  );

const cssPatch =
  Buffer.from(
    '',
    "hex",
  ).toString(
    "utf8",
  );

const uiFile =
  path.join(
    root,
    uiRelative,
  );

fs.mkdirSync(
  path.dirname(
    uiFile,
  ),
  {
    recursive:
      true,
  },
);

fs.writeFileSync(
  uiFile,
  uiModule,
  "utf8",
);

let main =
  fs.readFileSync(
    path.join(
      root,
      mainRelative,
    ),
    "utf8",
  );

if (
  !main.includes(
    'from "./pack09/uiPolish"',
  )
) {
  const customizationImport =
    /import\s*\{\s*installPack09Customization\s*,?\s*\}\s*from\s*["']\.\/pack09\/customization["']\s*;?/m;

  const match =
    main.match(
      customizationImport,
    );

  const importText =
`import {
  installPack09UiPolish,
} from "./pack09/uiPolish";`;

  if (
    match
  ) {
    main =
      main.replace(
        customizationImport,
        match[0] +
        "\n\n" +
        importText,
      );
  } else if (
    main.includes(
      'import "./style.css";',
    )
  ) {
    main =
      main.replace(
        'import "./style.css";',
        'import "./style.css";' +
        "\n\n" +
        importText,
      );
  } else {
    fail(
      "Nie znaleziono bezpiecznego miejsca na import UI Polish w main.ts.",
    );
  }
}

if (
  !main.includes(
    "installPack09UiPolish();",
  )
) {
  if (
    main.includes(
      "installPack09Customization();",
    )
  ) {
    main =
      main.replace(
        "installPack09Customization();",
        "installPack09Customization();" +
        "\n" +
        "installPack09UiPolish();",
      );
  } else if (
    main.includes(
      "installPack08UiQa();",
    )
  ) {
    main =
      main.replace(
        "installPack08UiQa();",
        "installPack08UiQa();" +
        "\n" +
        "installPack09UiPolish();",
      );
  } else {
    main +=
      "\ninstallPack09UiPolish();\n";
  }
}

fs.writeFileSync(
  path.join(
    root,
    mainRelative,
  ),
  main,
  "utf8",
);

const style =
  fs.readFileSync(
    styleFile,
    "utf8",
  );

fs.writeFileSync(
  styleFile,
  style.trimEnd() +
  "\n\n" +
  cssPatch.trim() +
  "\n",
  "utf8",
);

const rollbackPath =
  path.join(
    root,
    "ae-ui-polish-pack-10-rollback.mjs",
  );

const rollback =
`import fs from "node:fs";
import path from "node:path";

const root =
  process.cwd();

const backupRoot =
  ${JSON.stringify(
    backupRoot,
  )};

const manifestPath =
  path.join(
    backupRoot,
    "backup-manifest.json",
  );

if (
  !fs.existsSync(
    manifestPath,
  )
) {
  console.error(
    "Brak backupu:",
    manifestPath,
  );
  process.exit(
    1,
  );
}

const manifest =
  JSON.parse(
    fs.readFileSync(
      manifestPath,
      "utf8",
    ),
  );

const existed =
  new Set(
    manifest.existed,
  );

for (
  const relative of
    manifest.touched
) {
  const target =
    path.join(
      root,
      relative,
    );

  const backup =
    path.join(
      backupRoot,
      relative,
    );

  if (
    existed.has(
      relative,
    )
  ) {
    fs.mkdirSync(
      path.dirname(
        target,
      ),
      {
        recursive:
          true,
      },
    );

    fs.copyFileSync(
      backup,
      target,
    );
  } else {
    fs.rmSync(
      target,
      {
        recursive:
          true,
        force:
          true,
      },
    );
  }
}

console.log(
  "UI Polish Pack 10 cofnięty.",
);
`;

fs.writeFileSync(
  rollbackPath,
  rollback,
  "utf8",
);

console.log("");
console.log("==============================================");
console.log(" Animated Effects UI Polish Pack 10 INSTALLED");
console.log("==============================================");
console.log("");
console.log("Zakres: tylko UI/UX — bez zmian rendererów efektów.");
console.log("");
console.log("Zmiany:");
console.log(" - dwurzędowe karty efektów; nazwa nie jest zgniatana przez - / licznik / +");
console.log(" - Charakter efektu przeniesiony wysoko w inspectorze");
console.log(" - czytelniejsza kolejność sekcji inspectora");
console.log(" - poprawione nagłówki i padding paneli");
console.log(" - większy i czytelniejszy mikro-tekst");
console.log(" - bardziej kompaktowe filtry biblioteki");
console.log(" - responsywny header i menu");
console.log(" - większy użyteczny podgląd");
console.log(" - poprawione marginesy przy scrollbarach");
console.log(" - wyraźniejsze stany efektu aktywnego / podglądu");
console.log("");
console.log(
  "Backup:",
  path.relative(
    root,
    backupRoot,
  ),
);
console.log(
  "Rollback: .\\ae-ui-polish-pack-10-rollback.mjs",
);
console.log("");
console.log("Teraz:");
console.log("  pnpm --filter animated-effects run typecheck");
console.log("  pnpm --filter animated-effects run build");
